Fixpoint mem_denot (E : env) (base : word -> option byte) (log : list sentry)
  : word -> option byte :=
  match log with
  | [] => base
  | SE a w v :: rest =>
      wbytes (mem_denot E base rest) (adenot E a) (word_to_le_bytes w (edenot E v))
  end.

Lemma mem_denot_grows : forall E base log, mem_grows base (mem_denot E base log).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50|30;!1+_5+fJ!3'fL#<#;#2!2'fP#<#5!2'fQ#4!2'`S#<#3$E;R+^A$base;R%~R!1+^B!1,^C|600;!1+b\!1+^B!1,^C0$log;R1!5'`X+fJ$log;R1!2'fK#3!3'fL#4#3#1vd!1'fM#2!2'fK#2!3'fL#3#2!1,_3+fJ$a0;R+fJ-fJRN$s;R+fJ%l;R1%~R!2'fK#5!3'fL#6#5#1!2'fK#6!3'fL#7#6!3,_L+fJ#3#2#11$e_addr;R+^=$e_width;R+Y$e_val;R+P!3$a;R+^=$w;R+Y$v;R+P$rest;R1$IH;R!2'fK#:!3'fL#;#:#1vd!5'fN#;2!3'fO234#1!3'fR423!2'fK#;!3'fL#<#;!3,_L+fJ!3,fS#5#4#3#2#3#2#1#1").
Qed.

Definition estart (E : env) (a : saddr) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$E;R+^A$a;R+^=!2'^J!2'^H!1,^C|600;!2'`S#2!1'fT#1!1'fU#1").
Definition elenZ (E : env) (n : expr) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$E;R+^A$n;R+P!2'^H!1,^C|600;!2'`S#2#1").

