(* [comment removed for export] *)
Lemma rdn_one : forall mem (a : word) b,
  match mem a with Some b0 => Some b0 | None => seg_rom segs a end = Some b ->
  rdn segs mem a 1 = Some [b].
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S:0!1,^C|600;!1+^B0|30;!1+^B!1,^C2!1+b\3!2,c13#1!1+_53!1+b\6!1,_W6!1,_33$mem;R%x;R14$a;R1$b;R3$H;R!3+14-b\RN$x;R!1+b\34!1#3#22$b0;R35!2'g</segs;#25!6'X4!2,c13#2$o;R4!3+17-b\RN$x;R!1+b\37#12$b0;R3-b\RN$x;R!1+b\67!4'g8/segs;#6!3'g10#5!3,eX0!1,^[,_?,;,_S2$rest;R6!2,c16!3,_L3#2#188!2,c16!3,_L3#39!2,67!2,c16!3,_L3#29-b\RN$x;R!1+b\34!1#4#32$b0;R35!2'g</segs;#3#1").
Qed.

Lemma Z_to_bv8_mod : forall c, Z_to_bv 8 (c mod 256) = Z_to_bv 8 c.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S;0!1+^B#1!1+^B#2%~R!3+1!1+^B#3#2#1!3+1+S!2'^H#4#3!2'^H#4#2%~R!3+1+S!2'^H#3#2!2'^H#3#1!3+1!1+^B#4#3#2|30;!1,^C4!1,^[|800;!2'`=#26!2'^D57!2'^D5#2!1+_9+S$c;R+S&H;R$n;R+^G$b1;R0$b2;R1!5'V23%~R!3+1+S!2'^H#3#2!2'^H#3#1!3+1!1+^B#4#3#2$~R2$~R%~R!3+1+S!2'^H#4#3!2'^H#4#2!3+1!1+^B#5#4#3#1!3'^I#3#2#1%n;R+^G%b1;R0%b2;R13!4#1589!6'X+S!2'`=76$z;R+S!3+1+S#1!2'^H5!2'^D5#3!6'X+S7$z;R+S!3+1+S!2'`=!2'`=#366#1!3'cU#26&__arith;R&__wit;R!1,_3+_4!1+_5+_4&__varmap;R!1,_Y+S!1+_7+S&__ff;R!6,`@:'_:+_;+_;,_<!7,_8:'_:+_;+_;,_<!4,_=+S!2,_C+S6,_@!2,_C+S,^F,_E!2'_F:,_<!4'_G#1#3vv!2,6+2,4!3+1+2!2'_H#1#3,4!3'_I+S,^F#2%~R!3+1+S6,^F+9#1!2'^H59!1'qY#2!2'^H58!1'qY7").
Qed.

Lemma know_byte_lit_sound : forall E base kn rb rk b,
  know_ok segs E base kn ->
  know_byte_lit segs kn rb rk = Some b ->
