Lemma and_low_split_denot : forall segs E base kn bk j c dts rts (a : expr),
  know_ok segs E base kn -> (0 <= j)%Z -> (j < 64)%Z ->
  edenot E bk = Z_to_bv 64 (2 ^ j - 1) ->
  coeffs_divk kn (2 ^ j) dts = true ->
  eqm (uE E a) (c + tden E dts + tden E rts) ->
