Lemma sym_step_sound : forall E base rom ss ms i ss' scs scr scr' w,
  fetch_word segs (Z_to_bv 64 (s_pc ss)) = Some w ->
  is_ecall w = false ->
  decode_any w = Some (i, 4%Z) ->
  sym_step segs i (clr ss) scr = SOk ss' scs scr' ->
  scs_denot segs base E scs ->
  st_ok E base rom ss ms ->
  exists ms', RiscvSemantics.step segs ms = MachineOk ms'
              /\ st_okR E base rom ss' ms'.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S70!1,^C|600;|30;%~R!1+^B0!1+b\!1+^B!1,^C1|500;!1+^B!1,^C3!2+_Z+^`H+S|20;$E;R+^A$base;R2$rom;R2$ss;R+^^[$ms;R+^^\$i;R+^`H$ss';R+^^[$scs;R!1+_5+f\$scr;R+^_I$scr';R+^_I$w;R4$Hf;R!3+1!1+b\4!2'^`F/segs;!2'^D0!1'^_2#8!2,c14#1$He;R!3+1+2!1'^`G#2,7$Hd;R!3+1!1+b\5!1'^`I#3!2,c15!4,`\+^`H+S#8!1,^[6$Hs;R!3+1+^`K!4'^`L/segs;#9!1'^_8#;#6!3,^`M#8#7#5$Hsc;R!4'qJ/segs;#>#?#8$Hst;R!5'^_0#@#?#>#=#<!A'^c5#A#@#?!1'^_8#>#=#<#;#:#9#8#7#6#5#4#3#2!6'^c6#A#@#?#>#=#1").
Qed.

