Theorem sym_execS_sound : forall fuel first stops ss E base rom ms,
  st_ok segs E base rom ss ms ->
  exists ms', msteps segs ms ms' /\ st_ok segs E base rom (sym_execS segs fuel first stops ss) ms'.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S80|30;%~R!1+^B!1,^C|600;!1+b\!1+^B!1,^C0!1+b\+^=!1,_W+^=!5'^cS/segs;#:#9#8#7!3+12!1'^_;43!3+^c@/segs;#;#2!5'^cS/segs;#F#E#D#C$fuel;R+Y$first;R+2$stops;R!1+_5+S$ss;R+^^[$E;R+^A$base;R1$rom;R1$ms;R+^^\$Hst;R!6'^cK/segs;#4#3#2#5#1&a;R!9'^cT#9#8#7#6#5#4#3#2#1!2+^8!3+12!1'^_;!5'^cS/segs;#9#8#7#63!2+a<+^^\$ms';R+^^\!2+^8!3+^c@/segs;#3#1!6'^c?/segs;#6#5#44#1!5'V5!2+a<+^^\$ms';R+^^\!2+^8!3+^c@/segs;#4#1!6'^c?/segs;#7#6#5!5'^cS/segs;#;#:#9#8#1!2+a<+^^\$ms';R+^^\!2+^8!3+^c@/segs;#4#1!6'^cK/segs;#7#6#5!5'^cS/segs;#;#:#9#8#1$~R5$~R!2+a<+^^\$ms';R+^^\!2+^8!3+^c@/segs;#5#1!6'^c?/segs;#8#7#6!5'^cS/segs;#<#;#:#9#1!2$Hr;R!3+12!1'^_;!5'^cS/segs;#<#;#:#93$H;R!2+a<+^^\$ms';R+^^\!2+^8!3+^c@/segs;#7#1!6'^c?/segs;#:#9#8!5'^cS/segs;#>#=#<#;#1-a<RN$~R!2+a<+^^\$ms';R+^^\!2+^8!3+^c@/segs;#8#1!6'^c?/segs;#;#:#9!5'^cS/segs;#?#>#=#<#1!2+a<+^^\$ms';R+^^\!2+^8!3+^c@/segs;#9#1!6'^cK/segs;#<#;#:!5'^cS/segs;#@#?#>#=#1#11$x;R+^^\$~R!1$ms';R+^^\!2+^8!3+^c@/segs;#9#1!6'^c?/segs;#<#;#:!5'^cS/segs;#@#?#>#=#1#1!2$ms';R+^^\$H;R!2+^8!3+^c@/segs;#:#1!6'^c?/segs;#=#<#;!5'^cS/segs;#A#@#?#>#1!5'V6!6'^c?/segs;#>#=#<!5'^cS/segs;#B#A#@#?#2!2+a<+^^\$ms';R+^^\!2+^8!3+^c@/segs;#<#1!6'^cK/segs;#?#>#=!5'^cS/segs;#C#B#A#@#1$~R6$~R!6'^c?/segs;#?#>#=!5'^cS/segs;#C#B#A#@#3!2$Hms;R!3+^c@/segs;#=#4$Hst';R!6'^c?/segs;#A#@#?!5'^cS/segs;#E#D#C#B#5!4,^X+^^\$ms';R+^^\!2+^8!3+^c@/segs;#@#1!6'^cK/segs;#C#B#A!5'^cS/segs;#G#F#E#D#1#6!4,c5!3+^c@/segs;#?#6!6'^cK/segs;#B#A#@7#6#2!8'^cN/segs;#B#A#@7#6#1#:#2#1#1#2#1#2#1#1").
