Definition eagree (b : nat) (E E' : env) : Prop :=
  (forall n, (n < b)%nat -> ev E n = ev E' n) /\ eb E = eb E'.

Definition eupd (E : env) (i : nat) (v : word) : env := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S10!1+^B!1,^C|600;$E;R+^A$i;R+Y$v;R0!2,f:$n;R+Y-2RN$~R+20!2'^4#1#32#2!2'aX#4#1!1'b1#3").

