Lemma rdn_rd1 : forall mem n (a : word) bs j,
  rdn segs mem a n = Some bs -> (j < n)%nat ->
  rd1 mem (a + nat_to_word j) <> None.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SB0!1,^C|600;!1+^B0|30;!1,^C2!1+^B3!1+b\4!1+_54!1+b\6!2'^D3,^F!1,_34!3'g10#6!1'g2#4!2,c16!3,_L4#19!1,_W6!1,_W4!2,c16!3,_L4!4'eQ4#7#889!3+15!2,c14#2=!2'<+9#1!3+15==$mem;R%~R15$n;R+Y$a;R1$bs;R6$j;R+Y$H;R!3+17!4'g8/segs;#5#3#4!2,c16#2$Hj;R!2'f7#2#5&H1;R!8'^d;/segs;#7#6#5#4#3#2#1!3+17!4'g8/segs;#7!3'g10#5!1'g2#3}1!2,c16!3,_L4!4'eQ4#3#489vd&o;R-b\RN$x;R!1+b\45!1#8:2$b;R4!2,c14#1!2'g</segs;:5!1-b\RN$o;R!1+b\4%H1;R!3+17-b\RN$x;R!1+b\47#12$b;R4;<!2,c16!3,_L4!4'eQ4#6#789!1'`C!3+15#2=#12$b;R4!1$b;R4$H1;R!3+17;>vd$H0;R?&H2;R!6'85!2,c14#3$e;R5-b\RN$o;R!1+b\4w#12$~R4+:+9,;=#1+9@!1'`C?#1$H1;R!3+17<!2,c16!3,_L4!4'eQ4#5#689vd$H0;RA&H2;R!6'87<$e;R7-b\RN$o;R!1+b\6w#12$~R6+9+:,;>#2+9@!1'`CA#2!1'`C!3+15!2'^d:#8:=").
Qed.

(* [comment removed for export] *)
Lemma zf_covers_sound : forall E M0 allkn rb rk n kb kk len,
  know_ok segs E M0 allkn -> (n <= 8)%nat ->
  zf_covers allkn rb rk n kb kk len = true ->
