Lemma segs_avoid_find_none : forall l lo hi x,
  forallb (fun s => Z.leb hi (Z.of_N (seg_base s)) || Z.leb (Z.of_N (seg_base s) + Z.of_N (seg_size s)) lo) l = true ->
