Lemma wbytes_out : forall bs m (a x : word),
  (bv_unsigned a + Z.of_nat (length bs) <= 2 ^ 64)%Z ->
  (bv_unsigned x < bv_unsigned a \/ bv_unsigned a + Z.of_nat (length bs) <= bv_unsigned x)%Z ->
  wbytes m a bs x = m x.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S=0|30;!1+^B!1,^C0|600;!1,^C2!1+^B3!1+b\1!2'^H3#2|10;!2'^H3#3!2'^H3#4!2'_089!2'_1!2'^J9!1'b;!2'gK1#68!2'^H3#5$bs;R!1+_51$m;R%~R45$a;R4$x;R4$Hnw;R!2'_1!2'^J6!1'b;!2'gK1#4!2'^Z!1,^[7!1,^[2$H0;R!2+d3!2'_068!2'_1!2'^J8!1'b;!2'gK1#56!6'd4:;!3+15!4'fO#5#4#6#3!1#5#3$~R:!1$H;R!2'_09<!6'^eL#8#7#6#5#4#1#1$~R;!1$H;R!2'_1!2'^J<!1'b;!2'gK1#79!5'^eM#8#7#6#5#1#1#1").
