Lemma kzero_cut_sound : forall E M0 M M' allkn wb wk wn kb kk len,
  know_ok segs E M0 allkn ->
  kentry_ok segs E M (KZero (SA kb kk) len) ->
  (forall x : word,
     (bv_unsigned x < estart E (SA wb wk) \/ estart E (SA wb wk) + elenZ E wn <= bv_unsigned x)%Z ->
     M' x = M x) ->
  Forall (kentry_ok segs E M') (kzero_cut allkn wb wk wn kb kk len).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S90!1,^C|600;!1+^B0|30;!1,^C2!1+^B3!1+b\4%~R15!2'^H0#1!2'p4#>!2,^?#9#8$E;R+^A$M0;R6$M;R6$M';R%x;R15$allkn;R!1+_5+fY$wb;R+P$wk;R+S$wn;R+P$kb;R+P$kk;R+S$len;R+P$~R!4'kV/segs;#;#:#7$~R!4'mD/segs;#<#:!2,i;!2,^?#4#3#2$~R%x;R1%~R!2+d3!2'_078!2'_1!2'^J8!2'pD#>#77!3+15!1#<#2!1#=#2!A'^eR,i;$x;R5!3+15#1!2,c14!2'^D3,^F#>#=#<#;#:#9#8#7#6#5#4'^eS#3#2#1").
Qed.

Lemma kfill_cut_sound : forall c E M0 M M' allkn wb wk wn kb kk len,
  know_ok segs E M0 allkn ->
