(* [comment removed for export] *)
Lemma know_ok_unk_intro_pt : forall E M (a : saddr) (n : expr),
  flat E a (elenZ E n) ->
  (forall i, (0 <= i < elenZ E n)%Z -> M (Z_to_bv 64 (estart E a + i)) <> None) ->
  kentry_ok segs E M (KUnk a n).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S70!1,^C|600;|30;!1+^B!1,^C1!1+b\2!2'_1,^F#1!2'pD#6#3!1,_W2$E;R+^A$M;R%x;R!1+^B03$a;R+^=$n;R+P$Hfl;R!3'q4#4#2!2'pD#4#1$H;R%i;R+S%~R!2+^84!2'_0#15!1'`C!3+13!1#6!2'^D0!2'^J!2'p4#7#5#26vd!4,c5!3'q4#6#45%i;R+S%~R!2+^84!2'_0#1!2'pD#7#4!1'`C!3+13!1#7!2'^D0!2'^J!2'p4#8#6#26#2#1!4'mD/segs;#6#5!2,iG#4#3").
Qed.

(* [comment removed for export] *)
Lemma know_ok_unk_intro : forall E M (a : saddr) (bs : list byte) (ne : expr),
